/**
 * Finland Wildlife Collision 5-Sector Rotational Camera Plan
 * Hardware Fleet: 100 Physical Cameras per City (500 Total)
 * Annual Schedule: 5 Sectors per City × 1/5 Year (73 Days) Each = 500 Placements/City (2,500 Total)
 *
 * Data source: Ramboll Mobility Analytics — Hirvieläinonnettomuudet kartalla
 * (https://mobilityanalytics.ramboll.com/onn/hirvielain/), Finnish Wildlife Agency
 * (Suomen riistakeskus) official cervid road collision records 2021–2025, paired with
 * OpenStreetMap / Väylävirasto rural highway centerlines.
 */

export type SectorId = 1 | 2 | 3 | 4 | 5;
export type SectorFilter = 'all' | SectorId;

export interface SpeciesCollisionBreakdown {
  whiteTailedDeer: number;
  roeDeer: number;
  moose: number;
  fallowDeer: number;
  forestReindeer: number;
}

export interface CityDeploymentSector {
  sectorIndex: SectorId;
  code: string;
  name: string;
  directionLabel: string;
  shortPeriod: string;
  dayRangeLabel: string;
  center: { lat: number; lng: number };
  zoom: number;
  /** Convex Voronoi sector cell [lng, lat][]; clipped to city.borderLines when rendered */
  voronoiRing: Array<[number, number]>;
  cameraCount: number;
  historicalAccidents: number;
}

export type CompactPlannedCameraTuple = [
  unitNumber: number,
  sectorIndex: SectorId,
  lat: number,
  lng: number,
  bearingDeg: number,
  historicalAccidents: number,
  roadLabel: string,
];

export interface PlannedCameraNode {
  id: string;
  cityId: string;
  cityName: string;
  sectorIndex: SectorId;
  sectorName: string;
  sectorPeriod: string;
  unitNumber: number;
  rankInSector: number;
  rankInCity: number;
  clusterIndex: number;
  clusterSize: number;
  roadLabel: string;
  clusterLabel: string;
  lat: number;
  lng: number;
  bearingDeg: number;
  historicalAccidents: number;
  whiteTailedDeer: number;
  roeDeer: number;
  moose: number;
}

export interface CityCameraPlan {
  id: string;
  code: number;
  rank: number;
  name: string;
  region: string;
  prefix: string;
  primaryRoads: string;
  zoom: number;
  center: { lat: number; lng: number };
  totalAccidents: number;
  coveredAccidents: number;
  landAreaKm2: number;
  speciesTotals: SpeciesCollisionBreakdown;
  byYear: Record<string, number>;
  /** Municipal boundary polylines as [lng, lat][] rings */
  borderLines: Array<Array<[number, number]>>;
  /** Aggregated 2021–2025 collision prevalence cells as [lng, lat, collisionCount] */
  hotspots: Array<[number, number, number]>;
  /** 5 geographic sectors held sequentially for 1/5th of a year (73 days) each */
  sectors: CityDeploymentSector[];
  /** 500 annual roadside camera placements (5 sectors × 100 cameras) */
  cameras: PlannedCameraNode[];
}

export type CameraPriorityTier = 'critical' | 'high' | 'elevated';
export type CityWildlifeCameraPlan = CityCameraPlan;

