interface RawCityCameraPlan extends Omit<CityCameraPlan, 'cameras'> {
  rawCameras: CompactPlannedCameraTuple[];
}

function allocateSpecies(
  total: number,
  totals: SpeciesCollisionBreakdown
): { whiteTailedDeer: number; roeDeer: number; moose: number } {
  const denom = Math.max(1, totals.whiteTailedDeer + totals.roeDeer + totals.moose);
  const rw = (total * totals.whiteTailedDeer) / denom;
  const rr = (total * totals.roeDeer) / denom;
  const rm = (total * totals.moose) / denom;
  let w = Math.floor(rw);
  let r = Math.floor(rr);
  let m = Math.floor(rm);
  const rem = total - (w + r + m);
  const order: Array<'w' | 'r' | 'm'> = (
    [
      ['w', rw - w],
      ['r', rr - r],
      ['m', rm - m],
    ] as Array<['w' | 'r' | 'm', number]>
  )
    .sort((a, b) => b[1] - a[1])
    .map((x) => x[0]);
  for (let i = 0; i < rem; i++) {
    const k = order[i % 3];
    if (k === 'w') w++;
    else if (k === 'r') r++;
    else m++;
  }
  return { whiteTailedDeer: w, roeDeer: r, moose: m };
}

