export const TOP_5_WILDLIFE_ACCIDENT_CITIES: CityCameraPlan[] = RAW_TOP_5_CITIES.map((rawCity) => {
  const sectorMap = new Map(rawCity.sectors.map((s) => [s.sectorIndex, s]));
  const indexed = rawCity.rawCameras.map((tuple, idx) => ({ tuple, idx }));
  indexed.sort((a, b) => b.tuple[5] - a.tuple[5] || a.idx - b.idx);
  const cityRanks = new Array<number>(rawCity.rawCameras.length);
  indexed.forEach((item, rankZero) => {
    cityRanks[item.idx] = rankZero + 1;
  });

  const cameras: PlannedCameraNode[] = rawCity.rawCameras.map((tuple, idx) => {
    const [unitNumber, sectorIndex, lat, lng, bearingDeg, historicalAccidents, roadLabel] = tuple;
    const sec = sectorMap.get(sectorIndex)!;
    const sp = allocateSpecies(historicalAccidents, rawCity.speciesTotals);
    return {
      id: `${rawCity.prefix}-S${sectorIndex}-${String(unitNumber).padStart(3, '0')}`,
      cityId: rawCity.id,
      cityName: rawCity.name,
      sectorIndex,
      sectorName: sec.name,
      sectorPeriod: sec.shortPeriod,
      unitNumber,
      rankInSector: unitNumber,
      rankInCity: cityRanks[idx],
      clusterIndex: sectorIndex,
      clusterSize: 1,
      roadLabel,
      clusterLabel: `S${sectorIndex} (${sec.shortPeriod}) · ${roadLabel}`,
      lat,
      lng,
      bearingDeg,
      historicalAccidents,
      whiteTailedDeer: sp.whiteTailedDeer,
      roeDeer: sp.roeDeer,
      moose: sp.moose,
    };
  });

  const { rawCameras: _unused, ...rest } = rawCity;
  void _unused;
  return {
    ...rest,
    cameras,
  };
});

export const ALL_PLANNED_CAMERAS: PlannedCameraNode[] = TOP_5_WILDLIFE_ACCIDENT_CITIES.flatMap(
  (city) => city.cameras
);

export const TOTAL_TOP5_ACCIDENTS = TOP_5_WILDLIFE_ACCIDENT_CITIES.reduce(
  (sum, city) => sum + city.totalAccidents,
  0
);

export const TOTAL_COVERED_ACCIDENTS = TOP_5_WILDLIFE_ACCIDENT_CITIES.reduce(
  (sum, city) => sum + city.coveredAccidents,
  0
);
